const summaries={business:{name:'Founder Feast',line:'学会把一桌人配好。',price:'39.99加元 / 月，餐酒另付。',why:'先了解每个人正在做什么，再安排相关的人坐在一起。适合从小型晚餐开始，不靠大IP撑场。',avoid:'先不照搬低月费、高频活动和App开发。'},dating:{name:'BoL Selected',line:'学会把一场婚恋活动做好。',price:'1688元 / 人，本场约5小时。',why:'审核、手作、破冰、晚宴、互选，客户能看到一场具体服务。与我们的首发婚恋晚宴最接近。',avoid:'不照抄男女条件，也不把单场活动升级成能力尚未具备的高价长期婚介。'},travel:{name:'Other Way Round',line:'学会让陌生同行舒服地相处。',price:'1400英镑 / 人，墨西哥城4天3晚。',why:'年龄范围、行前信息、欢迎晚宴、主持人与当地专家分工，都能落实到执行。',avoid:'不照搬国外价格和合同，不把一个人报名当成单身核验。'}};
function select(id){const d=summaries[id];document.querySelectorAll('[data-select]').forEach(b=>{const active=b.dataset.select===id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});const box=document.getElementById('selection-result');box.replaceChildren();const left=document.createElement('div'),right=document.createElement('div');const h=document.createElement('h3');h.textContent=d.name;const p=document.createElement('p');p.textContent=d.line+' '+d.price;const link=document.createElement('a');link.href='#'+id;link.textContent='展开这家怎么做 ↓';left.append(h,p,link);for(const [label,copy]of [['为什么适合我们',d.why],['哪些先不照搬',d.avoid]]){const strong=document.createElement('strong');strong.textContent=label;const text=document.createElement('p');text.textContent=copy;right.append(strong,text)}box.append(left,right)}
document.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.select)));select('business');const menu=document.getElementById('menu'),nav=document.getElementById('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));const dialog=document.getElementById('lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.image;dialog.querySelector('img').alt=b.dataset.caption;document.getElementById('lightbox-caption').textContent=b.dataset.caption;dialog.showModal()}));document.getElementById('close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
